# Imageboard Default Configuration
# DO NOT EDIT THIS FILE DIRECTLY.
# Override any settings by defining them in board/config.py.

# Database Backend Configuration
# Options: 'sqlite', 'postgres', 'mysql'
DB_ENGINE = 'sqlite'

# Database Connection Details (used if DB_ENGINE != 'sqlite')
DB_NAME = 'pyuchan'
DB_USER = 'pyuchan_user'
DB_PASSWORD = ''
DB_HOST = '127.0.0.1'
DB_PORT = '5432'  # 5432 for Postgres, 3306 for MySQL

# Media processing
CONVERT_THUMBS_TO_WEBP = True
MAX_THUMB_SIZE = (250, 250)
JPEG_QUALITY = 95
WEBP_QUALITY = 90
THUMB_WEBP_QUALITY = 80

# Board defaults
THREADS_PER_PAGE = 15
MAX_BODY_LENGTH = 8000
ALLOW_EMPTY_COMMENT_WITH_FILE = True
DEFAULT_ANONYMOUS_NAME = "Anonymous"

# Moderation
DEFAULT_BAN_DURATION_DAYS = 3

# Permitted image and video formats
ALLOWED_IMAGE_EXTENSIONS = [
    ".jpg", ".jpeg", ".png", ".gif", ".webp"
]

ALLOWED_VIDEO_EXTENSIONS = [
    ".webm", ".mp4"
]

# Permitted non-image formats
ALLOWED_AUDIO_EXTENSIONS = [
    ".mp3", ".ogg", ".opus", ".flac", ".wav", ".m4a", ".aac",
    ".mod", ".it", ".xm", ".s3m", ".sid", ".nsf", ".spc", ".mid"
]

ALLOWED_ARCHIVE_EXTENSIONS = [
    ".zip", ".rar", ".7z", ".tar", ".gz", ".bz2", ".xz", ".lzh"
]

ALLOWED_DOCUMENT_EXTENSIONS = [
    ".pdf", ".txt", ".torrent"
]

# Update ALLOWED_EXTENSIONS to permit media beyond images and webm/mp4
ALLOWED_EXTENSIONS = (
    ALLOWED_IMAGE_EXTENSIONS +
    ALLOWED_VIDEO_EXTENSIONS +
    ALLOWED_AUDIO_EXTENSIONS +
    ALLOWED_ARCHIVE_EXTENSIONS +
    ALLOWED_DOCUMENT_EXTENSIONS
)

