# File size limits (in bytes)
MAX_FILE_SIZE = 20 * 1024 * 1024  # 20 MB

# Video thumbnailing
FFMPEG_PATH = "ffmpeg"
FFPROBE_PATH = "ffprobe"

# Cooldown periods in seconds
THREAD_COOLDOWN_SECONDS = 60
REPLY_COOLDOWN_SECONDS = 12

# Window to detect duplicate comments/files (in seconds)
DUPLICATE_CHECK_WINDOW_SECONDS = 300

# Hard cap on the number of posts in a single thread (prevents megathreads
# from exhausting memory/CPU when rendered or polled by the updater).
MAX_THREAD_POSTS = 1000

# Per-IP report rate limiting (in addition to the per-post 1h dedupe)
REPORTS_PER_WINDOW = 10
REPORT_WINDOW_SECONDS = 600

# Django template date format string
# m: month (01-12)
# d: day of month (01-31)
# y: 2-digit year (e.g. 26)
# D: 3-letter day of week (e.g. Thu)
# H: 24-hour hour (00-23)
# i: minutes (00-59)
# s: seconds (00-59)
POST_DATE_FORMAT = 'y/m/d(D)H:i:s'

# CAPTCHA Configuration
ENABLE_CAPTCHA = True                 # Master switch: set False to completely disable CAPTCHA
CAPTCHA_ON_THREAD_CREATION = True    # Require CAPTCHA when creating a new thread (OP)
CAPTCHA_ON_REPLY = False             # Require CAPTCHA when replying to a thread
CAPTCHA_LENGTH = 5                   # Number of glyphs in the challenge
CAPTCHA_EXPIRY_SECONDS = 300         # 5 minutes before token expires

# Thread Archiving Configuration
ENABLE_ARCHIVE = True             # Enable soft-archiving instead of immediate deletion
ARCHIVE_RETENTION_DAYS = 3        # Number of days an archived thread remains before deletion

# --- Proxy & DNSBL Anti-Spam Configuration ---
ENABLE_DNSBL = True  # Master switch for DNSBL checks
DNSBL_TIMEOUT_SECONDS = 1.5  # Prevent slow DNS queries from stalling post creation

# Standard reputation lists (DroneBL, StopForumSpam, SORBS-DUL/HTTP, EFnet RBL)
DNSBL_ZONES = [
    "b.barracudacentral.org",
    "dnsbl.dronebl.org",
    "rbl.efnetrbl.org",
    "sbl.spamhaus.org",
]

# Tor Exit Node Blocking
ENABLE_TOR_BLOCKING = True
# Official Tor Project DNS exit list query zone: <ip>.80.<server_ip>.ip-port.exitlist.torproject.org
# Using the general Tor DNSEL zone provides clean offline-compatible lookups:
TOR_DNSEL_ZONE = "exitlist.torproject.org"
